  nuvio: `<img src="data:image/png;base64," width="36" height="36" class="rounded-lg shrink-0 object-contain" alt="Nuvio" />`,
  arvio: `<img src="data:image/png;base64," width="36" height="36" class="rounded-lg shrink-0" alt="ARVIO" />`,
