// No services currently need the monogram fallback below, but the
// mechanism stays for any future integration with no brand asset.
const MONOGRAM_ICONS: Record<string, { label: string; classes: string }> = {};

export function connectionIconHtml(type: string): string {
  const raw = RAW_ICON_SVGS[type];
  if (raw) return raw;
  const brand = BRAND_ICON_PATHS[type];
  if (brand) {
    return `<svg width="36" height="36" viewBox="0 0 24 24" fill="${brand.fill}" class="shrink-0"><title>${type}</title><path d="${brand.path}"/></svg>`;
  }
  const mono = MONOGRAM_ICONS[type];
  if (mono) {
    return `<span class="w-9 h-9 rounded-lg ${mono.classes} text-sm font-bold flex items-center justify-center shrink-0">${mono.label}</span>`;
  }
  return `<span class="w-2 h-2 bg-zinc-500 rounded-full shrink-0"></span>`;
}
